-- ============================================
-- LUMA — Thème 10 : MOYEN 2/3 x4 — Une filature qui tourne mal
-- ============================================


update scenarios set content = '{"characters": {"partner": "votre collègue"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "(Radio) He''s leaving the building now, heading north on Main Street.", "text_fr": "(Radio) Il quitte le bâtiment maintenant, se dirigeant vers le nord sur Main Street.", "choices": [{"text": "Copy that, I''ll follow at a safe distance.", "text_fr": "Bien reçu, je vais suivre à distance sécuritaire.", "next": "n2"}, {"text": "I''ll cut through the alley to get ahead of him.", "text_fr": "Je vais couper par la ruelle pour le devancer.", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You maintain distance, blending into the evening crowd.)", "text_fr": "(Vous maintenez la distance, vous fondant dans la foule du soir.)", "choices": [{"text": "(Continue following, staying alert to his movements.)", "text_fr": "(Continue à suivre, en restant attentif à ses mouvements.)", "next": "n3"}]}, "n2b": {"speaker": "you_thought", "text": "(You take the alley shortcut, hoping to intercept him further down the street.)", "text_fr": "(Vous prenez le raccourci de la ruelle, espérant l''intercepter plus loin dans la rue.)", "choices": [{"text": "(Position yourself ahead, watching for him to pass.)", "text_fr": "(Positionne-toi devant, en surveillant son passage.)", "next": "n3"}]}, "n3": {"speaker": "partner", "text": "(Radio) He''s stopped at a café, seems to be waiting for someone.", "text_fr": "(Radio) Il s''est arrêté à un café, semble attendre quelqu''un.", "choices": [{"text": "I''ll find a spot nearby to observe without being noticed.", "text_fr": "Je vais trouver un endroit à proximité pour observer sans être remarqué.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(A woman approaches the suspect and hands him an envelope before quickly leaving.)", "text_fr": "(Une femme s''approche du suspect et lui remet une enveloppe avant de partir rapidement.)", "choices": [{"text": "(Try to get a photo of the woman before she disappears.)", "text_fr": "(Essaie de prendre une photo de la femme avant qu''elle ne disparaisse.)", "next": "n5"}, {"text": "(Focus on following the suspect instead, since he''s the primary target.)", "text_fr": "(Concentre-toi sur suivre le suspect plutôt, puisqu''il est la cible principale.)", "next": "n5b"}]}, "n5": {"speaker": "you_thought", "text": "(You manage to snap a clear photo just as she turns the corner.)", "text_fr": "(Vous parvenez à prendre une photo claire juste au moment où elle tourne au coin.)", "choices": [{"text": "Send the photo to the team for identification.", "text_fr": "Envoie la photo à l''équipe pour identification.", "next": "n6"}]}, "n5b": {"speaker": "you_thought", "text": "(The suspect pockets the envelope and continues walking briskly.)", "text_fr": "(Le suspect met l''enveloppe dans sa poche et continue à marcher d''un pas vif.)", "choices": [{"text": "(Continue following, staying focused on his next moves.)", "text_fr": "(Continue à suivre, en restant concentré sur ses prochains mouvements.)", "next": "n6"}]}, "n6": {"speaker": "you_thought", "text": "(Suddenly, the suspect glances back sharply — he seems to have noticed something.)", "text_fr": "(Soudain, le suspect jette un regard en arrière brusquement — il semble avoir remarqué quelque chose.)", "choices": [{"text": "(Duck into a nearby shop to avoid being seen.)", "text_fr": "(Réfugie-toi dans une boutique à proximité pour éviter d''être vu.)", "next": "n7"}, {"text": "(Keep walking naturally, acting like an ordinary pedestrian.)", "text_fr": "(Continue à marcher naturellement, en agissant comme un piéton ordinaire.)", "next": "n7b"}]}, "n7": {"speaker": "you_thought", "text": "(From inside the shop window, you watch him scan the street, then continue on, seemingly satisfied.)", "text_fr": "(Depuis la vitrine de la boutique, vous le regardez scanner la rue, puis continuer, apparemment satisfait.)", "choices": [{"text": "(Wait a moment, then resume the tail from a greater distance.)", "text_fr": "(Attends un moment, puis reprends la filature à plus grande distance.)", "next": "n8"}]}, "n7b": {"speaker": "you_thought", "text": "(He studies you for a tense moment, but seems to decide you''re not a threat.)", "text_fr": "(Il vous étudie pendant un moment tendu, mais semble décider que vous n''êtes pas une menace.)", "choices": [{"text": "(Continue past him, then double back carefully after some distance.)", "text_fr": "(Continue à le dépasser, puis fais demi-tour prudemment après une certaine distance.)", "next": "n8"}]}, "n8": {"speaker": "partner", "text": "(Radio) Good move. He''s turning into an apartment complex on Fifth Avenue.", "text_fr": "(Radio) Bon mouvement. Il tourne dans un complexe d''appartements sur la Cinquième Avenue.", "choices": [{"text": "I''ll note the address and we can investigate the building further.", "text_fr": "Je vais noter l''adresse et on pourra investiguer le bâtiment davantage.", "next": "n9"}]}, "n9": {"speaker": "you_thought", "text": "(You watch him enter a specific unit, noting the number carefully.)", "text_fr": "(Vous le regardez entrer dans une unité spécifique, en notant le numéro soigneusement.)", "choices": [{"text": "Report back to the team with this new location.", "text_fr": "Fais un rapport à l''équipe avec ce nouvel emplacement.", "next": "end_tracked"}]}, "end_tracked": {"speaker": "partner", "text": "Excellent work. This location just became a key piece of our investigation.", "text_fr": "Excellent travail. Cet emplacement vient de devenir une pièce clé de notre enquête.", "end": true, "ending_label": "Filature réussie malgré les imprévus 🕵️‍♀️🚶"}}}'::jsonb, is_playable = true
where title = 'Une filature qui tourne mal'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
